    correction: [{"quoi":"ننطلق من حصر x","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> ≤ x ≤ <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"نضرب في 2 الموجب","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> ≤ 2x ≤ 1</span>"},{"quoi":"نطرح <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span> من الأطراف","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - <span class=\"rad\"><span class=\"rcd\">2</span></span> ≤ E ≤ 1 - <span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"نقارن 1 بـ <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span></span>","math":"<span dir=\"ltr\" class=\"expr\">1 &lt; <span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E ≤ 1 - <span class=\"rad\"><span class=\"rcd\">2</span></span> &lt; 0</span>"}],
