    correction: [{"quoi":"نستعمل السؤال السابق","math":"<span dir=\"ltr\" class=\"expr\">E<sup>2</sup> = 14 - 4<span class=\"rad\"><span class=\"rcd\">6</span></span></span>"},{"quoi":"قاعدة الجذر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">E<sup>2</sup></span></span> = |E|</span>"},{"quoi":"نقارن العددين","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">2</span></span> &lt; 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"نرفع القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|2<span class=\"rad\"><span class=\"rcd\">3</span></span> - <span class=\"rad\"><span class=\"rcd\">2</span></span>| = 2<span class=\"rad\"><span class=\"rcd\">3</span></span> - <span class=\"rad\"><span class=\"rcd\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">14 - 4<span class=\"rad\"><span class=\"rcd\">6</span></span></span></span> = 2<span class=\"rad\"><span class=\"rcd\">3</span></span> - <span class=\"rad\"><span class=\"rcd\">2</span></span></span>"}],
