    correction: [{"quoi":"نستعمل السؤال السابق","math":"<span dir=\"ltr\" class=\"expr\">A = (x - 4)<sup>2</sup> - 16 + 12</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">(x - 4)<sup>2</sup> - 16 + 12 = (x - 4)<sup>2</sup> - 4</span>"},{"quoi":"نتعرّف على فرق مربّعين","math":"<span dir=\"ltr\" class=\"expr\">(x - 4)<sup>2</sup> - 4 = (x - 4)<sup>2</sup> - 2<sup>2</sup></span>"},{"quoi":"نستعمل المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(x - 4)<sup>2</sup> - 2<sup>2</sup> = ((x - 4) - 2)((x - 4) + 2)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = (x - 2)(x - 6)</span>"}],
