    correction: [{"quoi":"مساحة المثلث القائم","math":"<span dir=\"ltr\" class=\"expr\">S1 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> × BM × BC</span>"},{"quoi":"نعوّض و نختصر","math":"<span dir=\"ltr\" class=\"expr\">S1 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> × 2x × x = x<sup>2</sup></span>"},{"quoi":"مساحة المربّع","math":"<span dir=\"ltr\" class=\"expr\">S2 = (6 - 2x)<sup>2</sup></span>"},{"quoi":"ننشر المربّع","math":"<span dir=\"ltr\" class=\"expr\">(6 - 2x)<sup>2</sup> = 36 - 24x + 4x<sup>2</sup></span>"},{"quoi":"نطرح","math":"<span dir=\"ltr\" class=\"expr\">S2 - S1 = 36 - 24x + 4x<sup>2</sup> - x<sup>2</sup></span>"},{"quoi":"نضع 3 عاملا مشتركا","math":"<span dir=\"ltr\" class=\"expr\">36 - 24x + 3x<sup>2</sup> = 3(x<sup>2</sup> - 8x + 12)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">S2 - S1 = 3(x<sup>2</sup> - 8x + 12)</span>"}],
